styles='''*{box-sizing:border-box}body{overflow-wrap:anywhere;margin:0;background:#edf1f6;color:#172b45;font:16px/1.65 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1160px;margin:auto;padding:32px 22px 70px}header{background:#142b49;color:white;padding:34px;border-radius:16px;margin-bottom:24px}header small{color:#adc9f2}h1{font-size:30px;margin:8px 0}h2{font-size:23px;margin-top:0}h3{margin:8px 0}a{color:#1755a2;overflow-wrap:anywhere}header a{color:#c8dcff}section,.card{background:white;padding:24px;border-radius:12px;margin:18px 0;border:1px solid #d7e0ed}.note{padding:15px 18px;background:#fff3d8;border-left:4px solid #a97512;border-radius:6px}.good{background:#e9f5ed;border-color:#87bc9b}code,pre{font:13px/1.6 ui-monospace,monospace;overflow-wrap:anywhere}pre{white-space:pre-wrap;background:#f3f6fa;padding:16px;border-radius:8px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{border-bottom:1px solid #dce4ef;padding:12px;text-align:left;vertical-align:top}.scroll{overflow:auto}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.grid .card{margin:0}video,img{width:100%;max-height:320px;object-fit:contain;background:#132338;border-radius:8px}.badge{display:inline-block;padding:3px 10px;border-radius:30px;background:#fff1ce;color:#734b00;font-weight:650}button{background:#1755a2;color:white;padding:11px 16px;border:0;border-radius:7px;cursor:pointer;font-size:15px}button:disabled{background:#8b99aa;cursor:default}textarea{display:block;width:100%;min-height:75px;margin:8px 0 18px;padding:10px;border:1px solid #9babc1;border-radius:6px;font:inherit}label{display:block;padding:10px 0}input{width:20px;height:20px;vertical-align:middle}summary{cursor:pointer;font-weight:650}.muted{color:#526781}footer{padding:20px 0;color:#526781}@media(max-width:680px){main{padding:14px}.grid{grid-template-columns:1fr}header,section,.card{padding:18px}h1{font-size:25px}table{min-width:580px}}'''
