summary=f'''<section><h2>本轮验证事实</h2><div class="note">{h(control.get('exact_stop_reason',''))}</div><p>执行器原始结论：<strong>{h(live['decision'])}</strong>；独立验收状态：<strong>{h(control['product_status'])}</strong>。先前S2的9/9和历史截图仅证明旧候选，不能代替当前统一前端。</p><ul><li>统一页面、Windows启动链、真实媒体边界拒绝：已有本轮执行记录。</li><li>此前代码静审通过；本轮真实内容结论仍须独审裁决。{h(completion_note)}</li><li>{h(quality_note)}</li><li>11段人工留样保持NOT_RUN，冻结预期及视频字节均未改动。</li></ul><p><a href="{h(latest)}">真实终态收据</a> · <a href="{h(control['independent_review'])}">本轮独立审查</a> · <a href="reports/unified-media/independent-runtime-transition-01/review.md">启动竞态纠偏独审</a> · <a href="reports/authorization-program-v1-local-02.approval.json">已批准的本机持续授权</a> · <a href="{h(base)}/browser-result.json">浏览器原始记录</a> · <a href="reports/unified-media/independent-correction-01/review-87c64a3.md">初版历史代码审查</a> · <a href="reports/unified-media/independent-correction-01/review-0f6b772.md">历史执行器纠偏审查</a> · <a href="验收报告与盲测视频_S2历史.html">旧S2测试视频与输出（历史）</a></p></section>'''
steps=['双击LVW.exe → 打开图文视频工作台；保留服务窗口，以其显示地址为准。','服务面板启动本机Ollama，等待“启动中…”结束且分析按钮可用；资源不足时不能保证分析成功。','选择图片或视频并预览；人工稿先写一段文字，再点分析。','查看机器建议和原始JSON；视频应显示真实源PTS、时间基和哈希，不把四帧采样当作完整分镜。','点击采纳并确认替换，编辑后复制/导出TXT与JSON；未采纳的新结果不能覆盖旧稿。','新分析中取消，确认终态和资源released；模型关闭后仍应能编辑导出。','先保存导出文件，再关闭本页拥有的模型服务，最后在服务窗口Ctrl+C。']
guide='<section><h2>怎么体验</h2><ol>'+''.join(f'<li>{h(s)}</li>' for s in steps)+'</ol><p>图片：JPEG/PNG/WebP ≤20MiB、4000万像素。视频：MP4/MOV ≤256MiB、≤60秒、源帧≤8294400像素。工作稿只在当前页面会话中，刷新前请导出。完整数据库修订、批量、长视频、音频及完整V1质量尚未交付。</p></section>'
outline='<section><h2>完整开发大纲</h2><div class="scroll"><table><tr><th>阶段</th><th>交付</th><th>完成子步骤</th><th>说明</th></tr>'+''.join(f'<tr><td>{h(x["stage_id"])}</td><td>{h(x.get("title",""))}</td><td>{x["completed_substeps"]}/{x["total_substeps"]}</td><td>{h(x.get("summary",""))}</td></tr>' for x in control['development_outline'])+'</table></div><p>本次提前切片另计U1/U2/U3，不将切片完成度等同于完整R1/R2。</p></section>'
checks=read('.agent-governance/stages/R1/04-acceptance-matrix.md') if False else None
coverage_path=control.get('slice_acceptance_receipt')
coverage={v['id']:v for v in read(coverage_path)['rows']} if coverage_path and (ROOT/coverage_path).exists() else {}
names=['图片公开入口真实结果','媒体边界与损坏拒绝','视频源SHA与实际PTS','联合四帧模型结果','运行中取消与实际释放','显式采纳及导出来源','模型关闭后手工编辑导出','资源/原生进程/no-cloud','同一生产UI与双击入口','独立复算与完整清理']
rows=''
for i,name in enumerate(names,1):
 k=f'UM-{i:02d}';v=coverage.get(k) or live.get('checks',{}).get(k,{})
 rows+=f'<tr><td>{k}</td><td>{h(name)}</td><td>{h(v.get("status","未完成"))}</td><td>{h(v.get("basis",v.get("oracle","当前真实运行未证明，不计PASS")))}</td></tr>'
report=header+summary+'<section><h2>逐项验收</h2><div class="scroll"><table><tr><th>编号</th><th>义务</th><th>结果</th><th>证据边界</th></tr>'+rows+'</table></div><p><a href="reports/unified-media/offline-03/receipt.json">离线03收据（对应其记录候选）</a> · <a href="reports/unified-media/ui-cpu-01/receipt.json">CPU浏览器夹具6项（不代表真实模型）</a> · <a href="reports/unified-media/resource-diagnostic-03/receipt.json">最近资源诊断</a></p></section>'
def result_card(name,title,media,source_base=base):
    p=ROOT/source_base/name
    if not p.exists():return '<article><h3>'+h(title)+'</h3>'+media+'<p>未取得可用模型输出，不计通过。</p></article>'
    run=json.loads(p.read_text());spec=run.get('parsed_spec') or {}
    return '<article><h3>'+h(title)+'</h3>'+media+'<p><a href="'+h(source_base+'/'+name)+'">下载原始ModelRun JSON</a></p><h4>实际中文输出</h4><pre>'+h(spec.get('text_zh',''))+'</pre><h4>实际英文输出</h4><pre>'+h(spec.get('text_en',''))+'</pre><details><summary>查看事实／推断／未知及运镜动作</summary><pre>'+h(json.dumps({'domains':spec.get('domains'),'technical':spec.get('technical'),'frames':run.get('frames')},ensure_ascii=False,indent=2))+'</pre></details></article>'
report+='<section><h2>真实验收使用的素材与实际输出</h2><p>'+h(quality_note)+'</p><div class="grid">'+result_card('image-model-run.json','开发图片','<img src="reports/unified-media/dev-image.png" alt="开发用非私有结构图片">')+result_card('video-model-run.json','开发视频','<video controls preload="none" src="reports/v0-s2/fixture-preparation-02/fixtures/tracking.mov"></video><a href="reports/v0-s2/fixture-preparation-02/fixtures/tracking.mov" download>保存开发视频</a>')+'</div></section>'
if not has_outputs and (ROOT/'reports/unified-media/live-03/video-model-run.json').exists():
    historical='reports/unified-media/live-03'
    report+='<section><h2>上一轮已完成的模型输出 · 历史未通过</h2><p>以下来自a8a431d的live03，不是当前修复候选结果。原视频错误描述为静止，导致语义Major；不能把此历史输出当成当前候选通过。</p><div class="grid">'+result_card('image-model-run.json','live03历史图片结果','<img src="reports/unified-media/dev-image.png" alt="历史开发图片">',historical)+result_card('video-model-run.json','live03历史视频结果','<video controls preload="none" src="reports/v0-s2/fixture-preparation-02/fixtures/tracking.mov"></video>',historical)+'</div></section>'
report+='<section><h2>11段人工留样 · 未提交模型</h2><p>先看视频，再到统一工作台上传验证。以下预期由先验观察冻结，不是LVW实际输出；不用逐字匹配，也不要依据来源标题编造事实。正式机器门禁完成前不需要你代跑回归。</p><p><a href="人工验收视频集/人工验证视频_11段.zip" download>下载视频集ZIP</a> · <a href="人工验收视频集/expected-results.frozen.json">冻结预期</a> · <a href="reports/unified-media/holdout-binding.json">新旧候选与哈希绑定</a></p><div class="grid">'
for v,e in zip(freeze['videos'],expected['items']):
 assert v['id']==e['id']
 report+=f'<article class="card"><h3>{h(e["id"])} · {h(e["style"])}</h3><span class="badge">NOT_RUN</span><video controls preload="none" src="{h(v["video_path"])}"></video><p><a download href="{h(v["video_path"])}">保存视频</a> · {v["duration_seconds"]}秒</p><details><summary>查看冻结观察预期</summary><ul>'+''.join(f'<li>{h(s)}</li>' for s in e['must_observe'])+'</ul><p>不应臆造：'+h('；'.join(e['must_not_invent']))+'</p><pre>'+h(e['example_prompt'])+'</pre></details></article>'
report+='</div></section>'+outline
record=header+summary+guide+'<section><h2>我的体验记录</h2><p>仅保存本浏览器、此候选的辅助记录，不自动提交签署。</p>'
items=['统一入口能打开，无需ComfyUI','图片分析结果可用，原稿未被覆盖','视频可预览、分析，取样信息与结果可见','显式采纳并确认后可编辑、复制与导出','切换输入与重分析不自动覆盖人工稿','取消后终态/释放明确，旧稿保留','模型关闭后人工稿仍可编辑导出']
for i,label in enumerate(items):record+=f'<label><input type="checkbox" id="c{i}"> {h(label)}</label>'
record+='<label for="notes">问题、素材编号与导出文件位置</label><textarea id="notes"></textarea><button id="export">下载体验记录JSON</button> <span id="saved" role="status"></span><p>机器门禁未完成时不提供拟签署按钮；完成后也必须由你明确发回签署，勾选不等于批准。</p></section>'+outline
payload=json.dumps({'candidate_sha':candidate,'ready':ready},ensure_ascii=False)
script='''<script>const binding=BINDING,key='lvw-unified-human-'+binding.candidate_sha,ids=['c0','c1','c2','c3','c4','c5','c6','notes'];function data(){return {kind:'HUMAN_EXPERIENCE_DRAFT_NOT_SIGNATURE',candidate_sha:binding.candidate_sha,machine_ready:binding.ready,checks:ids.slice(0,7).map(id=>({id,experienced:document.getElementById(id).checked})),notes:document.getElementById('notes').value,human_signoff_submitted:false,stage_pass_claim:false}}try{const old=JSON.parse(localStorage.getItem(key)||'null');if(old?.candidate_sha===binding.candidate_sha){for(const x of old.checks||[])if(ids.includes(x.id))document.getElementById(x.id).checked=x.experienced===true;document.getElementById('notes').value=typeof old.notes==='string'?old.notes:''}}catch{}for(const id of ids)document.getElementById(id).addEventListener('input',()=>{try{localStorage.setItem(key,JSON.stringify(data()));document.getElementById('saved').textContent='已保存本机草稿'}catch{document.getElementById('saved').textContent='本机保存不可用，请下载'}});document.getElementById('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='LVW-unified-experience-'+binding.candidate_sha.slice(0,8)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};</script>'''.replace('BINDING',payload)
def page(title,body,js=''):
 return '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+title+'</title><style>'+styles+'</style><main>'+body+'<footer>离线证据导航，不运行模型、不替代产品前端，不自动签署或发布。</footer></main>'+js+'</html>'
(ROOT/'验收报告与盲测视频.html').write_text(page('LVW统一前端验收报告',report))
(ROOT/'人工验收指南.html').write_text(page('LVW统一前端体验指南',record,script))
print('Rendered current evidence report and candidate-bound guide; ready=',ready)
